445→      // WORKFLOW / CRON / RUNTIME — local-only (shell/process execution)
446→      workflow_create: { h: handleWorkflowCreate, s: ToolInputSchemas.workflow_create, d: DangerLevel.MODERATE, lo: true, p: P.WRITE },
447→      workflow_list:   { h: handleWorkflowList,   s: ToolInputSchemas.workflow_list,   d: DangerLevel.SAFE,     lo: true, p: P.READ },
448→      workflow_run:    { h: handleWorkflowRun,    s: ToolInputSchemas.workflow_run,    d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
449→      workflow_delete: { h: handleWorkflowDelete, s: ToolInputSchemas.workflow_delete, d: DangerLevel.MODERATE, lo: true, p: P.WRITE },
450→      cron_create:     { h: handleCronCreate,     s: ToolInputSchemas.cron_create,     d: DangerLevel.MODERATE, lo: true, p: P.WRITE },
