456→      browser_test:    { h: handleBrowserTest,     s: ToolInputSchemas.browser_test,    d: DangerLevel.MODERATE, lo: true, p: P.EXECUTE },
457→    };
458→
459→    for (const [name, meta] of Object.entries(builtins)) {
460→      const wTools = workspaceTools as Record<string, { description: string }>;
461→      const tTools = taskTools as Record<string, { description: string }>;
462→      const iTools = interactionTools as Record<string, { description: string }>;
463→      const gTools = githubTools as Record<string, { description: string }>;
464→      const pTools = pmTools as Record<string, { description: string }>;
465→      const webT = webTools as Record<string, { description: string }>;
466→      const brT = browserTools as Record<string, { description: string }>;
467→      const wfT = workflowTools as Record<string, { description: string }>;
468→
469→      const description = (wTools[name] || tTools[name] || iTools[name] || gTools[name] || pTools[name] || webT[name] || brT[name] || wfT[name])?.description || 'No description';
470→      logger.info(`Registering builtin tool: ${name}`, { hasHandler: !!meta.h });
471→
472→      this.register({
473→        name: name as ToolName,
474→        description,
475→        handler: meta.h,
476→        schema: meta.s,
477→        danger: meta.d,
478→        localOnly: meta.lo,
479→        permission: meta.p,
480→      });
481→    }
482→  }
483→}
