485→// ============================================================================
486→// Utility Functions
487→// ============================================================================
488→
489→function hasExplicitConfirmation(args: unknown): boolean {
490→  if (!args || typeof args !== 'object') return false;
491→  const record = args as Record<string, unknown>;
492→  return record.confirm === true;
493→}
494→
495→function _mapToOpenAIFunction(tool: OrchestratorTool): Record<string, unknown> {
496→  return {
497→    type: 'function',
498→    function: {
499→      name: tool.name,
500→      description: tool.description,
501→      parameters: zodToJsonSchema(tool.schema),
502→    },
503→  };
504→}
505→
506→function zodToJsonSchema(schema: z.ZodSchema): Record<string, unknown> {
507→  // Zod v4: use .type and .def instead of ._def.typeName
508→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
509→  const s = schema as any;
510→
511→  if (s.type === 'object' && s.def?.shape) {
512→    const shape = s.def.shape;
513→    const properties: Record<string, unknown> = {};
514→    const required: string[] = [];
515→
516→    for (const [key, value] of Object.entries(shape)) {
517→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
518→      const field = value as any;
519→
520→      // Use Zod v4's built-in isOptional() method
521→      const isOptional = typeof field.isOptional === 'function' ? field.isOptional() : false;
522→
523→      // Unwrap wrapper types to get the core type
524→      const innerSchema = unwrapZodType(field);
525→      properties[key] = zodTypeToJsonSchema(innerSchema, field);
526→
527→      if (!isOptional) required.push(key);
528→    }
529→
530→    const result: Record<string, unknown> = { type: 'object', properties };
531→    if (required.length > 0) result.required = required;
532→    return result;
533→  }
534→  return { type: 'object', properties: {} };
535→}
536→
537→/** Unwraps default/optional/nullable wrappers to reach core Zod type. */
538→// eslint-disable-next-line @typescript-eslint/no-explicit-any
539→function unwrapZodType(schema: any): any {
540→  let current = schema;
541→  while (current) {
542→    const type = current.type ?? current.def?.type;
543→    if (type === 'default' || type === 'optional' || type === 'nullable') {
544→      current = current.def?.innerType ?? current._def?.innerType;
545→    } else {
546→      return current;
547→    }
548→  }
549→  return schema;
550→}
551→
552→/** Converts one Zod field schema into JSON-schema-like descriptor. */
553→// eslint-disable-next-line @typescript-eslint/no-explicit-any
554→function zodTypeToJsonSchema(innerSchema: any, outerSchema?: any): Record<string, unknown> {
555→  const base: Record<string, unknown> = {};
556→
557→  // In Zod v4, .description is a direct property, also available via .meta()
558→  const desc = outerSchema?.description ?? innerSchema?.description;
559→  if (desc) base.description = desc;
560→
561→  const type = innerSchema?.type ?? innerSchema?.def?.type;
562→
563→  switch (type) {
564→    case 'string': return { ...base, type: 'string' };
565→    case 'number': return { ...base, type: 'number' };
566→    case 'boolean': return { ...base, type: 'boolean' };
567→    case 'enum': {
568→      // Zod v4: enum entries are in .def.entries as { key: value } or .values as array
569→      const entries = innerSchema.def?.entries;
570→      const values = entries ? Object.values(entries) : (innerSchema.values ?? innerSchema.options);
571→      return values ? { ...base, type: 'string', enum: values } : { ...base, type: 'string' };
572→    }
573→    case 'array': {
574→      const itemSchema = innerSchema.def?.element ?? innerSchema.def?.type;
575→      return { ...base, type: 'array', items: itemSchema ? zodTypeToJsonSchema(unwrapZodType(itemSchema)) : { type: 'string' } };
576→    }
577→    default: return { ...base, type: 'string' };
578→  }
579→}
580→
581→export const getToolRegistry = () => ToolRegistry.getInstance();
582→

